func TestNovelRiskBehavior(t *testing.T) {
	cases := []struct {
		name          string
		trial         Trial
		sponsorTrials int
		wantLevel     string
		minScore      int // score must be >= this
		maxScore      int // and <= this
	}{
		{
			name: "healthy late-phase trial scores low",
			trial: Trial{
				NCTID: "NCT1", Status: "RECRUITING", Enrollment: 500,
				Countries: []string{"United States", "Germany"}, Phases: []string{"PHASE3"},
				Sponsor: "Pfizer",
			},
			sponsorTrials: 200,
			wantLevel:     "low",
			minScore:      0, maxScore: 0,
		},
		{
			name: "terminated trial scores high",
			trial: Trial{
				NCTID: "NCT2", Status: "TERMINATED", WhyStopped: "lack of efficacy",
				Enrollment: 10, Countries: []string{"United States"}, Phases: []string{"PHASE1"},
				Sponsor: "Tiny Bio",
			},
			sponsorTrials: 1,
			wantLevel:     "high",
			minScore:      55, maxScore: 100,
		},
		{
			name: "sparse new-sponsor trial is moderate",
			trial: Trial{
				NCTID: "NCT3", Status: "RECRUITING", Enrollment: 60,
				Countries: []string{"Japan"}, Phases: []string{"PHASE2"},
				Sponsor: "New Lab",
			},
			sponsorTrials: 3,
			wantLevel:     "moderate",
			minScore:      25, maxScore: 54,
		},
		{
			name:          "missing fields accumulate risk",
			trial:         Trial{NCTID: "NCT4"},
			sponsorTrials: 0,
			wantLevel:     "high",
			minScore:      55, maxScore: 100,
		},
	}
	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			v := scoreRisk(tc.trial, tc.sponsorTrials)
			if v.Level != tc.wantLevel {
				t.Errorf("level = %q, want %q (score=%d)", v.Level, tc.wantLevel, v.Score)
			}
			if v.Score < tc.minScore || v.Score > tc.maxScore {
				t.Errorf("score = %d, want in [%d,%d]", v.Score, tc.minScore, tc.maxScore)
			}
			if len(v.Factors) == 0 {
				t.Error("expected at least one explainable factor, got none")
			}
			// Score must equal the sum of factor points, capped at 100.
			sum := 0
			for _, f := range v.Factors {
				sum += f.Points
			}
			if sum > 100 {
				sum = 100
			}
			if v.Score != sum {
				t.Errorf("score %d != capped factor sum %d", v.Score, sum)
			}
		})
	}
}

func TestHasAnyPhase(t *testing.T) {
	if !hasAnyPhase([]string{"PHASE2", "PHASE3"}, "PHASE3", "PHASE4") {
		t.Error("expected PHASE3 to match")
	}
	if hasAnyPhase([]string{"PHASE1"}, "PHASE3", "PHASE4") {
		t.Error("did not expect PHASE1 to match late phases")
	}
	if hasAnyPhase(nil, "PHASE1") {
		t.Error("nil phases should not match")
	}
}
